INSERT INTO knowledge_fact (domain, fact, boundary, gene_fit, season, source, reviewed) VALUES
  ('color', '白色也有色温：冷调肤色贴本白、冷白会把气色往上走，米白与奶油白里的黄调会把冷皮衬得发闷。', '中性肤色不挑冷暖，此时该看的是明度而不是色温。', '{}', '{autumn,winter}', '编辑整理（原型反解）', true),
  ('color', '显瘦靠的是轮廓与材质的一致性，不是颜色深浅：全黑且材质单一会变成一个没有边界的块。', '五官对比柔和的人大面积纯黑会被压成一片，需用不同材质分开层次。', '{"contrast":["low"]}', '{}', '编辑整理（原型反解）', true),
  ('color', '靠近脸的颜色会直接和肤色反应：不合适的色相放到离脸更远的位置（外套、下装），问题会小很多。', '暖调肤色贴脸反而顺，不需要刻意隔开。', '{"skinTone":["cool","neutral"]}', '{autumn,winter}', '编辑整理（原型反解）', true),
  ('color', '显白是对比度匹配，不是明度越高越好；颜色与五官对比度打架时，赢的通常是颜色。', '对比适中的人两头都能穿，但别同时用强对比与柔和色。', '{}', '{}', '编辑整理（原型反解）', true),
  ('color', '三色原则的后半句是关键：三个颜色里要有一个面积小、饱和度最高的主张色。', '全是中间调的配色看起来是没想好，不是低调。', '{}', '{}', '编辑整理（原型反解）', true),
  ('fit', '上装的肩线决定上半身的轮廓框架：决定它的是肩缝落在哪，不是袖子的宽窄。', '肩宽适中者两种都能穿，判断标准是肩缝落在肩点还是下落 1-2cm。', '{"shoulder":["narrow","broad"]}', '{autumn,winter}', '编辑整理（原型反解）', true),
  ('fit', '衣服的量感要匹配骨架的量感：超出骨架的那部分不会消失，只会把人的存在感压下去。', '骨架偏大者可以放心用一个强廓形单品做主角，其余收窄。', '{"frame":["small","medium"]}', '{}', '编辑整理（原型反解）', true),
  ('fit', '腰线的作用是给视线一个停顿点：落在躯干最窄的一段最稳，过高到肋下会显得刻意。', '腿身比偏长者正常腰位就够，再往上提反而失去优势。', '{"vertical":["long_torso","balanced"]}', '{}', '编辑整理（原型反解）', true),
  ('fit', '领口决定了露出的颈长，进而影响脸部的视觉大小：它是个比例问题，不是保暖问题。', '颈偏长者可以把领口做满，不用刻意留颈。', '{"neck":["short","medium"]}', '{autumn,winter}', '编辑整理（原型反解）', true),
  ('fit', '手腕是上肢最细的关节：露出它，等于在轮廓结束处给了一个细的信号。', '与露踝同理，不必买新衣服，袖长往上一点就够。', '{}', '{}', '编辑整理（原型反解）', true),
  ('proportion', '真正截断比例的是强对比的横向分割，不是身高本身；下装与鞋同色可以让视线不断线。', '身高有余量的人同样建议避开强对比的横向分割。', '{"heightBand":["petite","average"]}', '{}', '编辑整理（原型反解）', true),
  ('proportion', '外套下摆落在身体最宽处会横向切断：避开小腿中段比追求某个长度数字可靠。', '长款撑得住的人注意别让下摆正好停在小腿中段。', '{}', '{autumn,winter}', '编辑整理（原型反解）', true),
  ('proportion', '包是全身唯一可以随意移动的重点，它的落点会成为视觉重心。', '包的落点越低，重心越往下。', '{"heightBand":["petite","average"]}', '{}', '编辑整理（原型反解）', true),
  ('proportion', '脚踝是小腿最细处，露出它等于给下半身一个收尾；同样的裤子卷一道边就是两条裤子。', '气温很低时以保暖优先，不必硬露。', '{}', '{}', '编辑整理（原型反解）', true),
  ('fabric', '面料的量感要匹配骨架的量感：硬挺的厚面料会自己撑出形状，垂感面料顺着人走。', '骨架偏大者撑得住有结构的外套，硬挺面料能给轮廓。', '{"frame":["small","medium"]}', '{autumn,winter}', '编辑整理（原型反解）', true),
  ('fabric', '反光会让轮廓边界变模糊，视觉体积变大：哑光收边界，光泽扩边界。', '骨架小的人小面积光泽是加分项，一个缎面包或一双漆皮鞋就够。', '{"frame":["large","medium"]}', '{}', '编辑整理（原型反解）', true),
  ('fabric', '针距越粗，面料表面越不平整，视觉体积越大；保暖靠空气层，不靠纱线粗细。', '骨架偏大者可以把粗针当造型主角。', '{"frame":["small","medium"]}', '{autumn,winter}', '编辑整理（原型反解）', true),
  ('occasion', '正式度是个相对值：比目标岗位的日常着装高一级最稳，用力过猛比不够更难挽回。', '衡量的是你和那个场合的日常之间的距离，不是绝对的正装程度。', '{}', '{}', '编辑整理（原型反解）', true),
  ('howto', '卷袖两折互相压住才有摩擦力：第二折要压住第一折的边缘，这样它自己会锁住。', '只折一次的话，没有任何东西阻止它滑回去。', '{}', '{}', '编辑整理（原型反解）', true),
  ('howto', '塞衣角只塞前半段、两侧与背后自然垂落，比全塞更不紧绷，也保留腰线的停顿点。', '面料硬挺时全塞容易在腰部堆出一圈。', '{}', '{}', '编辑整理（原型反解）', true),
  ('outfit', '一身只留一个主角：其余单品降饱和度与结构复杂度，重点才成立。', '两个强廓形或两个主张色同时出现会让重点消失。', '{}', '{}', '编辑整理（原型反解）', true),
  ('outfit', '冬天叠穿靠厚度梯度（由薄到厚）而不是件数：层数堆到身上会先输给体积。', '细针织 + 薄羊毛的两层通常比一件粗针更暖也更利落。', '{}', '{autumn,winter}', '编辑整理（原型反解）', true);
INSERT INTO daily_content (user_id, gen_date, category, topic, lead, fit_text, why, visual, fact_ids, source, model_key, dedupe_key) VALUES
  (NULL, '1970-01-01', 'color', '冬天的白，不止一种', '本白、米白、奶油白——挂在架子上差不多，上身差很多。', '挑白和挑蓝一样：先看自己肤色的冷暖，再看明度。冷调皮贴本白更提气色，暖调皮带黄调的米白更顺。', '白色也有色温。挑白先看冷暖，再看明度。', '{"modality":"swatch","spec":{"items":[{"tone":"#FBFBF8","label":"本白","state":"pick"},{"tone":"#F2F4F1","label":"冷白","state":"pick"},{"tone":"#EFEADC","label":"米白","state":"drop"},{"tone":"#E6DECD","label":"奶油白","state":"drop"}]},"alt":"四种白色并排，本白与冷白适合，米白与奶油白不适合"}', '{}', 'fallback', '', 'color.white.tone'),
  (NULL, '1970-01-01', 'color', '全黑并不自动显瘦', '黑色显瘦这句话，只对了一半。', '大面积纯黑要先解决层次：用不同材质分开轮廓，比继续加深颜色更安全。', '显瘦靠的是轮廓和材质的一致性，不是颜色的深浅。', '{"modality":"compare","spec":{"left":{"label":"材质单一","tone":"#5A6156"},"right":{"label":"材质分层","tone":"#8E9A83","layered":true},"marker":"材质层次"},"alt":"同样是黑，左边材质单一，右边靠材质分出层次"}', '{}', 'fallback', '', 'color.allblack.myth'),
  (NULL, '1970-01-01', 'color', '驼色是个陷阱', '驼色大衣人人有，但不是人人都能贴近脸穿。', '不确定时把驼色放在外套或下半身，内搭用本白或灰蓝隔开，让靠近脸的颜色更安全。', '靠近脸的颜色会直接和肤色反应。不合适的色相放远一点，问题会小很多。', '{"modality":"diagram","spec":{"kind":"body","items":[{"label":"贴近脸的内搭","state":"avoid"},{"label":"外套","state":"pick"},{"label":"下装","state":"pick"}]},"alt":"驼色应避开贴脸的内搭，放在外套或下装"}', '{}', 'fallback', '', 'color.camel.proximity'),
  (NULL, '1970-01-01', 'color', '最亮的那个不一定最显白', '挑显白色时，多数人会选最亮的一档。', '先判断自己的五官对比度：对比强的人适合强对比的色，对比柔和的人选中等明度更稳。', '显白是对比度匹配，不是明度越高越好。', '{"modality":"swatch","spec":{"items":[{"tone":"#2F3540","label":"强对比","state":"pick"},{"tone":"#7E8A72","label":"中间调"},{"tone":"#D8D3C6","label":"柔和色"}]},"alt":"三档对比度的颜色，从强对比到柔和色"}', '{}', 'fallback', '', 'color.contrast.match'),
  (NULL, '1970-01-01', 'color', '三色原则里，得有一个跳出来', '全身不超过三个颜色，是被说滥的一条。真正容易漏的是后半句。', '三个颜色里要有一个是主张色：面积小但饱和度最高，其余两色压住。', '没有焦点的配色看起来是没想好，不是低调。', '{"modality":"swatch","spec":{"items":[{"tone":"#C9CFD4","label":"底色"},{"tone":"#8E9A83","label":"辅助色"},{"tone":"#B4674D","label":"主张色","state":"pick"}]},"alt":"三色配色，主张色面积小但最跳"}', '{}', 'fallback', '', 'color.three.accent'),
  (NULL, '1970-01-01', 'fit', '落肩在退潮，肩线回来了', '这两季的风衣和西装都在收肩。这是个信号。', '看肩缝位置：落在肩点上更精神，下落 1-2cm 更松弛；选哪个取决于你想要哪种轮廓。', '上装的肩线决定上半身的轮廓框架——决定它的不是袖子的宽窄，是肩缝落在哪。', '{"modality":"compare","spec":{"left":{"label":"落肩 · 肩缝下滑","tone":"#8A8F83"},"right":{"label":"肩缝落在肩点","tone":"#8E9A83","layered":true},"marker":"肩点位置"},"alt":"落肩与结构肩的对比"}', '{}', 'fallback', '', 'silhouette.shoulder.line'),
  (NULL, '1970-01-01', 'fit', 'Oversize 不是越大越遮', '很多人以为宽松等于藏。超出骨架的量感，会反过来吞掉人。', '只留一个维度宽松就够：肩正常、身宽，或者身正常、袖宽，不要三个一起放大。', '衣服的量感要匹配骨架的量感。超出太多的部分不会消失，只会把人的存在感压下去。', '{"modality":"compare","spec":{"left":{"label":"肩、身、袖一起放大","tone":"#8A8F83"},"right":{"label":"只留一处宽松","tone":"#8E9A83","layered":true},"marker":"廓形量感"},"alt":"整体放大与只留一处宽松的对比"}', '{}', 'fallback', '', 'silhouette.oversize.volume'),
  (NULL, '1970-01-01', 'proportion', '腰线不是越高越好', '提高腰线是常识，但提到哪才是关键。', '腰线落在躯干最窄的那一段最稳，比尽量高更可靠；高到肋下会显得刻意。', '腰线的作用是给视线一个停顿点。落在最窄处才成立。', '{"modality":"diagram","spec":{"kind":"body","items":[{"label":"过高 · 到肋下","state":"avoid"},{"label":"躯干最窄处","state":"pick"},{"label":"自然腰位"}]},"alt":"三个腰线位置，最窄处最稳"}', '{}', 'fallback', '', 'silhouette.waist.point'),
  (NULL, '1970-01-01', 'fit', '领口不只是一个开口', '同样是高领季，领口的形状决定了别人看到的颈长。', '颈偏短时避开全包高领，换成小 V 领或只到下巴下两指的半高领；颈偏长可以把领口做满。', '领口决定了露出的颈长，进而影响脸部的视觉大小。', '{"modality":"compare","spec":{"left":{"label":"全包高领 · 不留颈","tone":"#8A8F83"},"right":{"label":"半高领 / 小 V 领","tone":"#8E9A83","layered":true},"marker":"露出的颈长"},"alt":"全包高领与半高领的对比"}', '{}', 'fallback', '', 'silhouette.neckline.length'),
  (NULL, '1970-01-01', 'fit', '露腕，是最便宜的显瘦', '不用买新衣服，袖子往上一点就够。', '把袖口推到腕骨上方，或者选九分袖，给上半身的轮廓一个收尾。', '手腕是上肢最细的关节。露出它，等于在轮廓结束处给了一个细的信号。', '{"modality":"diagram","spec":{"kind":"scale","items":[{"label":"盖住手腕"},{"label":"刚到腕骨"},{"label":"腕骨上方","state":"pick"}]},"alt":"袖长三个位置，腕骨上方最利落"}', '{}', 'fallback', '', 'silhouette.sleeve.wrist'),
  (NULL, '1970-01-01', 'color', '显矮的元凶是截断，不是身高', '深色上衣 + 浅色裤子 + 黑鞋，视觉上被切成三段。', '让下装和鞋同色，腿在视觉上就不断；冬天穿靴子最容易做到。', '真正截断比例的是强对比，不是身高本身。同色延伸不断线。', '{"modality":"compare","spec":{"left":{"label":"上下截成三段","tone":"#3F463C"},"right":{"label":"下装与鞋同色","tone":"#4A5245","layered":true},"marker":"视线是否断线"},"alt":"三段配色与同色延伸的对比"}', '{}', 'fallback', '', 'proportion.cut.continuous'),
  (NULL, '1970-01-01', 'proportion', '外套下摆停在哪，比长度数字重要', '同样一件大衣，下摆落点差几厘米，效果差很多。', '避开小腿最粗的那一段：落在膝上或脚踝上方更稳。', '下摆落在身体最宽处会横向切断。避开宽度峰值，比追求某个长度数字更可靠。', '{"modality":"diagram","spec":{"kind":"body","items":[{"label":"膝上","state":"pick"},{"label":"小腿中段","state":"avoid"},{"label":"脚踝附近","state":"pick"}]},"alt":"外套下摆三个落点，小腿中段应避开"}', '{}', 'fallback', '', 'proportion.coat.hem'),
  (NULL, '1970-01-01', 'proportion', '包背在哪，重心就在哪', '包不只是装东西，它是全身最显眼的一个点。', '想强调上半身就背包在高处，想拉长就让它靠近腰线；包带太长会把重心带下去。', '包是全身唯一一个可以随意移动的重点。它的落点会成为视觉重心。', '{"modality":"diagram","spec":{"kind":"body","items":[{"label":"胸前"},{"label":"腰线附近","state":"pick"},{"label":"胯部"}]},"alt":"位置轴自上而下：胸前、腰线附近、胯部，腰线附近最稳"}', '{}', 'fallback', '', 'proportion.bag.position'),
  (NULL, '1970-01-01', 'fit', '裤长露踝，比例立刻不一样', '同样的裤子，卷一道边就是两条裤子。', '裤脚落在脚踝骨上方，或者卷一道边露出来，给下半身一个收尾。', '和露腕同理：在最细的关节处收口，轮廓会显得更利落。', '{"modality":"compare","spec":{"left":{"label":"盖住脚踝","tone":"#8A8F83"},"right":{"label":"露出脚踝","tone":"#8E9A83","layered":true},"marker":"裤长"},"alt":"长裤与九分裤的对比"}', '{}', 'fallback', '', 'proportion.pants.ankle'),
  (NULL, '1970-01-01', 'fabric', '冬天的厚，不等于硬', '同样是厚，垂下去的和撑起来的，穿在小骨架上是两回事。', '骨架偏小时选垂感好的细针织、薄羊毛；骨架够大时硬挺面料能给你轮廓。', '面料的量感要匹配骨架的量感。不是越厚越暖，也不是越挺越有型。', '{"modality":"compare","spec":{"left":{"label":"硬挺 · 自己撑出形状","tone":"#8A8F83"},"right":{"label":"垂感 · 顺着你走","tone":"#8E9A83","layered":true},"marker":"面料量感"},"alt":"硬挺面料与垂感面料的对比"}', '{}', 'fallback', '', 'fabric.drape.volume'),
  (NULL, '1970-01-01', 'fabric', '光泽会放大体积', '缎面、漆皮、金属感——好看，但它们有物理副作用。', '把光泽放在配饰或小面积处：一个缎面包或一双漆皮鞋就够，不必全身。', '反光会让轮廓边界变模糊，体积看起来更大。哑光收边界，光泽扩边界。', '{"modality":"compare","spec":{"left":{"label":"哑光 · 收边界","tone":"#5A6156"},"right":{"label":"光泽 · 扩边界","tone":"#8E9A83","layered":true},"marker":"反光"},"alt":"哑光与光泽面料的对比"}', '{}', 'fallback', '', 'fabric.sheen.volume'),
  (NULL, '1970-01-01', 'fabric', '针织的粗细，本身就是体积', '粗针和细针，差的不是保暖，是占地。', '骨架偏小时选细针、平针，保暖靠层数不靠粗细；骨架够大可以把粗针当主角。', '针距越粗，面料表面越不平整，视觉体积越大。保暖靠空气层，不靠纱线粗细。', '{"modality":"compare","spec":{"left":{"label":"粗针 · 纹理有体积","tone":"#8A8F83"},"right":{"label":"细针 · 平整","tone":"#8E9A83","layered":true},"marker":"针距"},"alt":"粗针与细针的对比"}', '{}', 'fallback', '', 'fabric.knit.gauge'),
  (NULL, '1970-01-01', 'occasion', '面试的正式度，差一级比差三级稳', '多数人要么穿得不够，要么用力过猛。', '比目标岗位的日常着装高一级就够：Smart Casual 通常是最安全的一档。', '正式度是个相对值。它衡量的是你和那个场合的日常之间的距离。', '{"modality":"diagram","spec":{"kind":"scale","items":[{"label":"休闲"},{"label":"Smart Casual","state":"pick"},{"label":"正式"},{"label":"礼服"}]},"alt":"正式度刻度，推荐 Smart Casual"}', '{}', 'fallback', '', 'occasion.interview.formality'),
  (NULL, '1970-01-01', 'howto', '袖子怎么卷，才不会滑下来', '卷袖是日常动作，但多数人卷完半小时就松了。', '先翻一次到肘下，再把袖口往上折到刚好盖住翻边——第二折压住第一折的边缘，它自己会锁住。', '两折互相压住才有摩擦力。只折一次的话，没有任何东西阻止它滑回去。', '{"modality":"video","spec":{"durationSec":12,"steps":2},"alt":"卷袖两步演示：翻到肘下，再折回盖住翻边"}', '{}', 'fallback', '', 'howto.sleeve.roll'),
  (NULL, '1970-01-01', 'outfit', '一身只留一个主角', '两件都很强的时候，重点就没了。', '先定主角单品，其余降饱和度与结构复杂度：其余单品的任务是让主角成立。', '一身的视觉重点只能有一个，两个强点会互相抵消。', '{"modality":"swatch","spec":{"items":[{"tone":"#2F3540","label":"主角 · 强结构","state":"pick"},{"tone":"#8E9A83","label":"配角 · 收住"},{"tone":"#C9CFD4","label":"底色"}]},"alt":"一身里主角、配角与底色的配比"}', '{}', 'fallback', '', 'outfit.one.hero');
